SIGNS=(("♈","Овен","смело сделать первый шаг"),("♉","Телец","сохранить спокойствие и верный ритм"),("♊","Близнецы","заметить возможность раньше других"),("♋","Рак","услышать важное между строк"),("♌","Лев","вдохновить окружающих уверенностью"),("♍","Дева","навести порядок в главном"),("♎","Весы","найти честный компромисс"),("♏","Скорпион","разобраться в сложной ситуации"),("♐","Стрелец","увидеть перспективу"),("♑","Козерог","довести решение до результата"),("♒","Водолей","предложить необычный ход"),("♓","Рыбы","выбрать верные слова"))
A=("Сегодня не стоит распыляться: одна ясная цель даст больше, чем десяток начатых дел.","Обстоятельства сложатся удачнее, если не торопить события и прислушаться к интуиции.","День может принести полезный разговор или неожиданную идею, способную изменить планы к лучшему.")
B=("Не берите на себя чужие обещания и оставьте немного свободы для спонтанного решения.","В общении спокойный тон окажется убедительнее споров и поспешных выводов.","Не игнорируйте небольшую деталь: именно она поможет выбрать правильное направление.")
def pick(x,d,s,k): return x[int(hashlib.sha256(f"{d}:{s}:{k}".encode()).hexdigest(),16)%len(x)]
def post(d,i,s,p): return f"<b>{i} {s.upper()} — {d:%d.%m.%Y}</b>\n\n{pick(A,d,s,'a')} {pick(B,d,s,'b')} Ваша сила сегодня — {p}."
def send(x):
 t=os.environ['TELEGRAM_BOT_TOKEN'].strip(); r=urllib.request.Request(f"https://api.telegram.org/bot{t}/sendMessage",data=urllib.parse.urlencode(x).encode(),method='POST'); urllib.request.urlopen(r,timeout=30).read()
d=datetime.now(ZoneInfo('Europe/Moscow')).date()
for i,s,p in SIGNS: send({'chat_id':'@proastrologi','text':post(d,i,s,p),'parse_mode':'HTML'}); time.sleep(1)
